/**
 * Unit tests for StdDateFormat#parseAsISO8601.
 * Since the method is protected, we use a subclass to access it.
 */
public class StdDateFormat_parseAsISO8601_TriageGen0Test {

    private TestableStdDateFormat dateFormat;

    // Subclass to expose protected method for testing
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(TimeZone tz, Locale loc, boolean lenient) {
            super(tz, loc);
            setLenient(lenient);
        }

        @Override
        public Date parseAsISO8601(String dateStr, ParsePosition pos, boolean throwErrors) throws ParseException {
            return super.parseAsISO8601(dateStr, pos, throwErrors);
        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParsePlainDate() throws ParseException {
        // len <= 10 and last char is digit
        Date result = dateFormat.parseAsISO8601("2023-10-27", new ParsePosition(0), true);
        Calendar cal = Calendar.getInstance();
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(27, cal.get(Calendar.DAY_OF_MONTH));
    }


















}

