        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }











    @Test
    public void testParseWithTimeZoneAndVaryingTimeLengths() throws ParseException {
        // Test various branches in the timeLen < 12 block

        // case 11: 2023-10-27T10:00:00+05 (len-T-6 = 11)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00+05", new ParsePosition(0), true));

        // case 10: 2023-10-27T10:00:0+05 (len-T-6 = 10)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:0+05", new ParsePosition(0), true));

        // case 9: 2023-10-27T10:00:+05 (len-T-6 = 9)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:+05", new ParsePosition(0), true));

        // case 8: 2023-10-27T10:00+05 (len-T-6 = 8)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00+05", new ParsePosition(0), true));

        // case 6: 2023-10-27T10:0+05 (len-T-6 = 6)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:0+05", new ParsePosition(0), true));

        // case 5: 2023-10-27T10+05 (len-T-6 = 5)
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10+05", new ParsePosition(0), true));
    }








}

